#include <iostream>
#include <vector>
#include <iomanip>
#include <string>

struct Eleve {
    std::string nom;
    std::vector<int> notes;
};

double moyenneEleve(const Eleve& e) {
    if (e.notes.empty()) {
        return 0;
    }
    int somme = 0;
    for (int n : e.notes) {
        somme += n;
    }
    return static_cast<double>(somme) / e.notes.size();
}

std::string mention(double m) {
    if (m >= 16) { return "Très bien"; }
    if (m >= 14) { return "Bien"; }
    if (m >= 12) { return "Assez bien"; }
    if (m >= 10) { return "Passable"; }
    return "Insuffisant";
}

const Eleve& major(const std::vector<Eleve>& classe) {
    int meilleur = 0;
    for (int i = 1; i < (int) classe.size(); i++) {
        if (moyenneEleve(classe[i]) > moyenneEleve(classe[meilleur])) {
            meilleur = i;
        }
    }
    return classe[meilleur];
}

int main() {
    int n;
    std::cin >> n;
    std::vector<Eleve> classe;
    int ignorees = 0;
    for (int i = 0; i < n; i++) {
        Eleve e;
        int k;
        std::cin >> e.nom >> k;
        for (int j = 0; j < k; j++) {
            int note;
            std::cin >> note;
            if (note >= 0 && note <= 20) {
                e.notes.push_back(note);
            } else {
                ignorees++;
            }
        }
        classe.push_back(e);
    }
    double total = 0;
    std::cout << std::fixed << std::setprecision(2);
    for (const Eleve& e : classe) {
        double m = moyenneEleve(e);
        total += m;
        std::cout << std::left << std::setw(8) << e.nom << m << " " << mention(m) << "\n";
    }
    std::cout << "Moyenne de la classe : " << total / classe.size() << "\n";
    std::cout << "Major : " << major(classe).nom << "\n";
    std::cout << "Notes ignorées : " << ignorees << "\n";
    return 0;
}
